def odd_one_out(input_string):
    char_count = {}
    for char in input_string:
        char_count[char] = char_count.get(char, 0) + 1

    unpaired_chars = []
    for char in reversed(input_string):
        if char_count[char] % 2 != 0 and char not in unpaired_chars:
            unpaired_chars.append(char)

    return unpaired_chars[::-1]
